sourceFiles.app.go:
package main

import (
	"context"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"sync"
	"time"

	"github.com/pkg/browser"
	wailsRuntime "github.com/wailsapp/wails/v2/pkg/runtime"
	"google.golang.org/api/gmail/v1"
)

type App struct {
	ctx             context.Context
	store           *LocalStore
	auth            *AuthService
	sync            *SyncEngine
	clients         map[string]*gmail.Service
	syncingAccounts map[string]bool
	syncMu          sync.Mutex
	activeAccount   string // "ALL" or specific email
	activeSplit     string // "MAIN", "NEWSLETTERS", "UPDATES", "ALL"
	mu              sync.RWMutex
}

func NewApp() *App {
	home, _ := os.UserHomeDir()
	dbDir := filepath.Join(home, ".fastmail")
	_ = os.MkdirAll(dbDir, 0700)
	dbPath := filepath.Join(dbDir, "mail.db")

	store, err := NewLocalStore(dbPath)
	if err != nil {
		fmt.Printf("Failed to initialize store: %v\n", err)
	}

	auth, _ := NewAuthService()
	syncEngine := NewSyncEngine(nil, store)

	return &App{
		store:           store,
		auth:            auth,
		sync:            syncEngine,
		clients:         make(map[string]*gmail.Service),
		syncingAccounts: make(map[string]bool),
		activeAccount:   "ALL",
		activeSplit:     "MAIN",
	}
}

func (a *App) startup(ctx context.Context) {
	a.ctx = ctx

	if a.auth == nil {
		auth, err := NewAuthService()
		if err == nil {
			a.auth = auth
		}
	}

	if a.auth != nil {
		accounts := a.auth.ListAccounts()
		for _, acc := range accounts {
			tok, err := a.auth.LoadTokenForAccount(acc)
			if err == nil && tok != nil {
				srv, err := a.auth.NewGmailClient(ctx, tok)
				if err == nil {
					a.mu.Lock()
					a.clients[acc] = srv
					a.mu.Unlock()
					a.EmitLog("INFO", fmt.Sprintf("Initialized client for %s", acc))
				} else {
					a.EmitLog("WARN", fmt.Sprintf("Failed to initialize client for %s: %v", acc, err))
				}
			}
		}

		if len(a.clients) > 0 {
			a.activeAccount = "ALL"
			// Run initial delta check on startup
			go func() {
				time.Sleep(1 * time.Second)
				_ = a.SyncInbox()
			}()

			// Start 5-minute fallback background delta-sync ticker
			go func() {
				ticker := time.NewTicker(5 * time.Minute)
				defer ticker.Stop()
				for range ticker.C {
					_ = a.SyncInbox()
				}
			}()
		}
	}
}

func (a *App) EmitLog(level, message string) {
	timestamp := time.Now().Format("15:04:05")
	fmt.Printf("[%s] [%s] %s\n", timestamp, level, message)
	if a.ctx != nil {
		wailsRuntime.EventsEmit(a.ctx, "log:entry", map[string]string{
			"timestamp": timestamp,
			"level":     level,
			"message":   message,
		})
	}
}

func (a *App) GetAccounts() []string {
	a.mu.RLock()
	defer a.mu.RUnlock()

	accountSet := make(map[string]bool)
	for acc := range a.clients {
		accountSet[acc] = true
	}
	if a.auth != nil {
		for _, acc := range a.auth.ListAccounts() {
			accountSet[acc] = true
		}
	}

	var list []string
	for acc := range accountSet {
		list = append(list, acc)
	}
	return list
}

func (a *App) GetActiveAccount() string {
	a.mu.RLock()
	defer a.mu.RUnlock()
	return a.activeAccount
}

func (a *App) SetActiveAccount(account string) {
	a.mu.Lock()
	defer a.mu.Unlock()
	a.activeAccount = account
}

func (a *App) GetActiveSplit() string {
	a.mu.RLock()
	defer a.mu.RUnlock()
	if a.activeSplit == "" {
		return "MAIN"
	}
	return a.activeSplit
}

func (a *App) SetActiveSplit(split string) {
	a.mu.Lock()
	a.activeSplit = split
	acc := a.activeAccount
	a.mu.Unlock()

	a.EmitLog("INFO", fmt.Sprintf("Split switched to: '%s' (Account: %s)", split, acc))
}

func (a *App) GetSplitInboxes() ([]SplitInboxDef, error) {
	if a.store == nil {
		return []SplitInboxDef{}, nil
	}
	return a.store.GetSplitInboxes()
}

func (a *App) SaveSplitInbox(split SplitInboxDef) error {
	if a.store == nil {
		return fmt.Errorf("store not initialized")
	}
	a.EmitLog("INFO", fmt.Sprintf("Saving Split: ID='%s', Name='%s', Type='%s', Value='%s'", split.ID, split.Name, split.FilterType, split.FilterValue))
	err := a.store.SaveSplitInbox(split)
	if err != nil {
		a.EmitLog("ERROR", fmt.Sprintf("SaveSplitInbox failed: %v", err))
	} else {
		a.EmitLog("INFO", fmt.Sprintf("Split '%s' saved successfully", split.Name))
	}
	return err
}

func (a *App) DeleteSplitInbox(id string) error {
	if a.store == nil {
		return fmt.Errorf("store not initialized")
	}
	a.EmitLog("INFO", fmt.Sprintf("Deleting Split ID='%s'", id))
	return a.store.DeleteSplitInbox(id)
}

func (a *App) GetSplitCounts() map[string]int {
	if a.store == nil {
		return map[string]int{}
	}
	a.mu.RLock()
	acc := a.activeAccount
	a.mu.RUnlock()

	counts, err := a.store.GetSplitCounts(acc)
	if err != nil {
		a.EmitLog("WARN", fmt.Sprintf("GetSplitCounts error: %v", err))
		return map[string]int{}
	}
	return counts
}

func (a *App) IsAuthenticated() bool {
	a.mu.RLock()
	defer a.mu.RUnlock()
	return len(a.clients) > 0
}

// AddAccount triggers Google OAuth in browser and saves token specifically for the returned email
func (a *App) AddAccount() (string, error) {
	if a.auth == nil {
		auth, err := NewAuthService()
		if err != nil {
			a.EmitLog("ERROR", "credentials.json not found in ~/.fastmail/credentials.json")
			return "", fmt.Errorf("Please place your credentials.json file into ~/.fastmail/credentials.json")
		}
		a.auth = auth
	}

	authURL := a.auth.GetAuthURL()
	codeChan := make(chan string)
	srv := a.auth.StartLocalCallbackServer(codeChan)

	a.EmitLog("INFO", "Opening browser for Google OAuth consent...")
	_ = browser.OpenURL(authURL)

	go func() {
		code := <-codeChan
		_ = srv.Shutdown(context.Background())
		a.EmitLog("INFO", "OAuth code received, exchanging for access token...")

		tok, err := a.auth.ExchangeCode(context.Background(), code)
		if err != nil {
			a.EmitLog("ERROR", fmt.Sprintf("Token exchange failed: %v", err))
			return
		}

		client, err := a.auth.NewGmailClient(context.Background(), tok)
		if err != nil {
			a.EmitLog("ERROR", fmt.Sprintf("Failed to initialize Gmail client: %v", err))
			return
		}

		// Discover the email address of the authenticated user
		email, err := a.auth.GetUserEmail(context.Background(), client)
		if err != nil {
			a.EmitLog("WARN", "Could not get email profile, fallback to user")
			email = fmt.Sprintf("account_%d@gmail.com", time.Now().Unix())
		}

		_ = a.auth.SaveTokenForAccount(email, tok)

		a.mu.Lock()
		a.clients[email] = client
		a.mu.Unlock()

		a.EmitLog("INFO", fmt.Sprintf("Account connected: %s. Starting background sync...", email))
		_ = a.SyncAccount(email)
		wailsRuntime.EventsEmit(a.ctx, "accounts:updated", a.GetAccounts())
	}()

	return "Authentication opened in browser", nil
}

// GetThreads returns cached threads filtered by active account and active split with pagination
func (a *App) GetThreads(limit, offset int) ([]EmailThread, error) {
	a.EmitLog("DEBUG", fmt.Sprintf("[GetThreads] ENTER limit=%d, offset=%d", limit, offset))
	if a.store == nil {
		a.EmitLog("WARN", "[GetThreads] store is nil — returning empty")
		return []EmailThread{}, nil
	}
	if limit <= 0 {
		limit = 100
	}
	a.mu.RLock()
	acc := a.activeAccount
	split := a.activeSplit
	a.mu.RUnlock()

	a.EmitLog("DEBUG", fmt.Sprintf("[GetThreads] Querying store: acc='%s', split='%s', limit=%d, offset=%d", acc, split, limit, offset))
	threads, err := a.store.GetInboxThreads(acc, split, limit, offset)
	if err != nil {
		a.EmitLog("ERROR", fmt.Sprintf("GetThreads failed (acc='%s', split='%s'): %v", acc, split, err))
		return []EmailThread{}, err
	}

	a.EmitLog("INFO", fmt.Sprintf("[GetThreads] Loaded %d threads for Split='%s' (Account='%s', Offset=%d)", len(threads), split, acc, offset))
	return threads, nil
}

// SearchThreads queries local SQLite FTS5 index filtered by active account and split
func (a *App) SearchThreads(query string) ([]EmailThread, error) {
	if a.store == nil || query == "" {
		return a.GetThreads(100, 0)
	}
	a.mu.RLock()
	acc := a.activeAccount
	split := a.activeSplit
	a.mu.RUnlock()

	return a.store.SearchThreads(query, acc, split)
}

// GetThreadMessages fetches full conversation for a thread
func (a *App) GetThreadMessages(threadID, accountEmail string) ([]EmailMessage, error) {
	a.mu.RLock()
	client, exists := a.clients[accountEmail]
	if !exists {
		// Fallback to any client
		for _, c := range a.clients {
			client = c
			break
		}
	}
	a.mu.RUnlock()

	if client == nil {
		return nil, fmt.Errorf("no client available for %s", accountEmail)
	}

	a.sync.SetService(client)
	return a.sync.FetchFullThread(context.Background(), threadID, accountEmail)
}

// DownloadAttachment downloads an attachment
func (a *App) DownloadAttachment(msgID, attachmentID, filename, threadID string) (string, error) {
	return a.sync.DownloadAttachment(context.Background(), msgID, attachmentID, filename, threadID)
}

// OpenAttachment opens downloaded file with macOS default application
func (a *App) OpenAttachment(localPath string) error {
	if runtime.GOOS == "darwin" {
		return exec.Command("open", localPath).Start()
	}
	return nil
}

// RevealInFinder reveals downloaded file in macOS Finder
func (a *App) RevealInFinder(localPath string) error {
	if runtime.GOOS == "darwin" {
		return exec.Command("open", "-R", localPath).Start()
	}
	return nil
}

// SyncAccount syncs a single account using DeltaSync if historyId exists, otherwise InitialSync
func (a *App) SyncAccount(email string) error {
	a.mu.Lock()
	client, exists := a.clients[email]
	if !exists || client == nil {
		a.mu.Unlock()
		return fmt.Errorf("account not found: %s", email)
	}

	// Concurrency guard: Skip if sync is already actively executing for this account
	if a.syncingAccounts[email] {
		a.mu.Unlock()
		return nil
	}
	a.syncingAccounts[email] = true
	a.mu.Unlock()

	go func() {
		defer func() {
			a.mu.Lock()
			a.syncingAccounts[email] = false
			a.mu.Unlock()
		}()

		engine := NewSyncEngine(client, a.store)
		lastHistID, _ := a.store.GetLastHistoryID(email)

		// 1. If we have a historyId, attempt lightning-fast DeltaSync first
		if lastHistID != "" {
			changed, err := engine.DeltaSync(
				context.Background(),
				email,
				lastHistID,
				func(level, msg string) { a.EmitLog(level, msg) },
			)

			if err == nil {
				wailsRuntime.EventsEmit(a.ctx, "sync:complete", email)
				if changed > 0 {
					wailsRuntime.EventsEmit(a.ctx, "threads:updated", email)
				}
				return
			}

			// If history ID was too old, fall through to full sync
			a.EmitLog("WARN", fmt.Sprintf("[%s] HistoryId expired or invalid (%v). Falling back to full pagination...", email, err))
		}

		// 2. Full initial sync
		a.EmitLog("INFO", fmt.Sprintf("[%s] Performing initial sync...", email))
		_ = engine.SyncAllInbox(
			context.Background(),
			email,
			func(level, msg string) {
				a.EmitLog(level, msg)
			},
			func(fetched, total, remaining int) {
				percent := 0
				if total > 0 {
					percent = (fetched * 100) / total
				}
				wailsRuntime.EventsEmit(a.ctx, "sync:progress", map[string]interface{}{
					"account":   email,
					"fetched":   fetched,
					"total":     total,
					"remaining": remaining,
					"percent":   percent,
				})
			},
		)
		wailsRuntime.EventsEmit(a.ctx, "sync:complete", email)
	}()

	return nil
}

// SyncHistoricMail explicitly resumes or continues the historical mailbox pagination for all or active accounts
func (a *App) SyncHistoricMail() error {
	a.mu.RLock()
	accounts := a.GetAccounts()
	active := a.activeAccount
	a.mu.RUnlock()

	if len(accounts) == 0 {
		a.EmitLog("ERROR", "No accounts connected to backfill.")
		return fmt.Errorf("no accounts connected")
	}

	targetAccounts := accounts
	if active != "" && active != "ALL" {
		targetAccounts = []string{active}
	}

	for _, email := range targetAccounts {
		a.mu.RLock()
		client, exists := a.clients[email]
		a.mu.RUnlock()
		if !exists || client == nil {
			continue
		}

		go func(accEmail string, gmailClient *gmail.Service) {
			a.syncMu.Lock()
			if a.syncingAccounts[accEmail] {
				a.syncMu.Unlock()
				a.EmitLog("WARN", fmt.Sprintf("[%s] Sync already in progress, skipping duplicate request.", accEmail))
				return
			}
			a.syncingAccounts[accEmail] = true
			a.syncMu.Unlock()
			wailsRuntime.EventsEmit(a.ctx, "sync:start", accEmail)

			defer func() {
				a.syncMu.Lock()
				delete(a.syncingAccounts, accEmail)
				a.syncMu.Unlock()
			}()

			engine := NewSyncEngine(gmailClient, a.store)
			a.EmitLog("INFO", fmt.Sprintf("[%s] Starting/Resuming full historical backfill...", accEmail))
			_ = engine.SyncAllInbox(
				context.Background(),
				accEmail,
				func(level, msg string) { a.EmitLog(level, msg) },
				func(fetched, total, remaining int) {
					percent := 0
					if total > 0 {
						percent = (fetched * 100) / total
					}
					wailsRuntime.EventsEmit(a.ctx, "sync:progress", map[string]interface{}{
						"account":   accEmail,
						"fetched":   fetched,
						"total":     total,
						"remaining": remaining,
						"percent":   percent,
					})
				},
			)
			wailsRuntime.EventsEmit(a.ctx, "sync:complete", accEmail)
			wailsRuntime.EventsEmit(a.ctx, "threads:updated", accEmail)
		}(email, client)
	}

	return nil
}

// SyncInbox triggers synchronization for active account (or all accounts if "ALL")
func (a *App) SyncInbox() error {
	a.mu.RLock()
	accounts := a.GetAccounts()
	a.mu.RUnlock()

	if len(accounts) == 0 {
		a.EmitLog("ERROR", "No accounts connected to sync.")
		return fmt.Errorf("no accounts connected")
	}

	if a.activeAccount != "" && a.activeAccount != "ALL" {
		return a.SyncAccount(a.activeAccount)
	}

	// Sync all accounts in parallel
	for _, acc := range accounts {
		_ = a.SyncAccount(acc)
	}
	return nil
}

