package main

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"os"
	"path/filepath"
	"strings"

	"golang.org/x/oauth2"
	"golang.org/x/oauth2/google"
	"google.golang.org/api/gmail/v1"
	"google.golang.org/api/option"
)

type AuthService struct {
	config *oauth2.Config
}

type AccountInfo struct {
	Email string `json:"email"`
}

func credentialsFilePath() string {
	home, _ := os.UserHomeDir()
	return filepath.Join(home, ".fastmail", "credentials.json")
}

func tokensDir() string {
	home, _ := os.UserHomeDir()
	dir := filepath.Join(home, ".fastmail", "tokens")
	_ = os.MkdirAll(dir, 0700)
	return dir
}

func NewAuthService() (*AuthService, error) {
	credPath := credentialsFilePath()
	data, err := os.ReadFile(credPath)
	if err != nil {
		data, err = os.ReadFile("credentials.json")
		if err != nil {
			return nil, fmt.Errorf("credentials.json not found in ~/.fastmail/ or project directory")
		}
	}

	// Request GmailReadonlyScope specifically
	cfg, err := google.ConfigFromJSON(data, gmail.GmailReadonlyScope)
	if err != nil {
		return nil, fmt.Errorf("failed to parse credentials.json: %w", err)
	}

	cfg.RedirectURL = "http://localhost:8089/oauth/callback"

	return &AuthService{config: cfg}, nil
}

func (a *AuthService) ListAccounts() []string {
	var accounts []string
	entries, err := os.ReadDir(tokensDir())
	if err != nil {
		return accounts
	}

	for _, entry := range entries {
		if !entry.IsDir() && strings.HasSuffix(entry.Name(), ".json") {
			email := strings.TrimSuffix(entry.Name(), ".json")
			// Filter out temporary fallback account names if any exist
			if !strings.HasPrefix(email, "account_") {
				accounts = append(accounts, email)
			}
		}
	}
	return accounts
}

func (a *AuthService) LoadTokenForAccount(email string) (*oauth2.Token, error) {
	path := filepath.Join(tokensDir(), email+".json")
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	tok := &oauth2.Token{}
	err = json.NewDecoder(f).Decode(tok)
	return tok, err
}

func (a *AuthService) SaveTokenForAccount(email string, token *oauth2.Token) error {
	path := filepath.Join(tokensDir(), email+".json")
	f, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE|os.O_TRUNC, 0600)
	if err != nil {
		return err
	}
	defer f.Close()
	return json.NewEncoder(f).Encode(token)
}

func (a *AuthService) RemoveAccountToken(email string) error {
	path := filepath.Join(tokensDir(), email+".json")
	return os.Remove(path)
}

func (a *AuthService) GetAuthURL() string {
	// prompt=consent and access_type=offline guarantees a full refresh token with Gmail scopes
	return a.config.AuthCodeURL("state-token", oauth2.AccessTypeOffline, oauth2.ApprovalForce)
}

func (a *AuthService) ExchangeCode(ctx context.Context, code string) (*oauth2.Token, error) {
	return a.config.Exchange(ctx, code)
}

func (a *AuthService) NewGmailClient(ctx context.Context, token *oauth2.Token) (*gmail.Service, error) {
	client := a.config.Client(ctx, token)
	return gmail.NewService(ctx, option.WithHTTPClient(client))
}

func (a *AuthService) GetUserEmail(ctx context.Context, srv *gmail.Service) (string, error) {
	profile, err := srv.Users.GetProfile("me").Context(ctx).Do()
	if err != nil {
		return "", fmt.Errorf("failed to fetch profile: %w", err)
	}
	return profile.EmailAddress, nil
}

func (a *AuthService) StartLocalCallbackServer(codeChan chan<- string) *http.Server {
	srv := &http.Server{Addr: ":8089"}

	http.HandleFunc("/oauth/callback", func(w http.ResponseWriter, r *http.Request) {
		code := r.URL.Query().Get("code")
		if code != "" {
			fmt.Fprintf(w, "<html><body style='font-family:system-ui;text-align:center;padding:50px;background:#1e1e20;color:white;'><h2>Account Connected!</h2><p>You can close this tab and return to FastMail.</p></body></html>")
			codeChan <- code
		} else {
			fmt.Fprintf(w, "Authentication failed.")
		}
	})

	go func() {
		_ = srv.ListenAndServe()
	}()

	return srv
}

