package main

import (
	"strings"
)

type SplitCategory string

const (
	SplitMain        SplitCategory = "MAIN"
	SplitNewsletters SplitCategory = "NEWSLETTERS"
	SplitUpdates     SplitCategory = "UPDATES"
	SplitSocial      SplitCategory = "SOCIAL"
)

type SplitInboxDef struct {
	ID          string `json:"id"`
	Name        string `json:"name"`
	ShortcutKey string `json:"shortcutKey"`
	FilterType  string `json:"filterType"`  // "CATEGORY", "QUERY", "SENDER"
	FilterValue string `json:"filterValue"` // "MAIN", "NEWSLETTERS", "from:github.com", etc.
	IsSystem    bool   `json:"isSystem"`
	SortOrder   int    `json:"sortOrder"`
	Count       int    `json:"count"`
}

// ClassifyThreadWithRules evaluates custom user rules first, then falls back to defaults
func ClassifyThreadWithRules(labelIDs []string, sender, subject, snippet string, customSplits []SplitInboxDef) string {
	senderLower := strings.ToLower(sender)
	subjectLower := strings.ToLower(subject)
	snippetLower := strings.ToLower(snippet)

	// 1. Check custom user-defined rules first
	for _, split := range customSplits {
		if split.IsSystem || split.FilterValue == "" {
			continue
		}
		term := strings.ToLower(split.FilterValue)
		// Check sender domain / keyword match or subject / snippet match
		if strings.Contains(senderLower, term) || strings.Contains(subjectLower, term) || strings.Contains(snippetLower, term) {
			return split.ID
		}
	}

	return ClassifyThread(labelIDs, sender, subject, snippet)
}

// ClassifyThread determines the split category using Gmail label IDs and robust local heuristics
func ClassifyThread(labelIDs []string, sender, subject, snippet string) string {
	labelsMap := make(map[string]bool)
	for _, l := range labelIDs {
		labelsMap[strings.ToUpper(strings.TrimSpace(l))] = true
	}

	senderLower := strings.ToLower(sender)
	subjectLower := strings.ToLower(subject)
	snippetLower := strings.ToLower(snippet)

	// 1. Gmail System Category Labels
	if labelsMap["CATEGORY_PROMOTIONS"] {
		return string(SplitNewsletters)
	}
	if labelsMap["CATEGORY_UPDATES"] {
		return string(SplitUpdates)
	}
	if labelsMap["CATEGORY_SOCIAL"] {
		return string(SplitSocial)
	}

	// 2. Social Networks
	socialDomains := []string{
		"linkedin.com", "twitter.com", "x.com", "discord.com", "facebookmail.com",
		"instagram.com", "redditmail.com", "reddit.com", "quora.com", "tiktok.com",
	}
	for _, domain := range socialDomains {
		if strings.Contains(senderLower, domain) {
			return string(SplitSocial)
		}
	}

	// 3. Newsletters & Marketing Digests
	newsletterKeywords := []string{
		"substack.com", "beehiiv.com", "mailchimp", "seeking alpha", "seekingalpha",
		"newsletter", "weekly digest", "daily digest", "daily briefing", "edition #",
		"morning brew", "the hustle", "medium.com", "tldr", "curated by",
		"roundup", "dispatch", "techcrunch", "bloomberg", "the verge", "wired",
		"investing.com", "fool.com", "axios", "hackernewsletter", "changelog.com",
	}
	for _, kw := range newsletterKeywords {
		if strings.Contains(senderLower, kw) || strings.Contains(subjectLower, kw) {
			return string(SplitNewsletters)
		}
	}

	if strings.Contains(snippetLower, "unsubscribe") ||
		strings.Contains(snippetLower, "view in browser") ||
		strings.Contains(snippetLower, "email preferences") ||
		strings.Contains(snippetLower, "manage your subscription") {
		return string(SplitNewsletters)
	}

	// 4. Automated Notifications / Receipts / Transactional Alerts
	automatedSenders := []string{
		"noreply", "no-reply", "notifications@", "notification@", "billing@",
		"receipts@", "receipt@", "orders@", "order@", "security@", "support@",
		"alerts@", "alert@", "donotreply@", "automated@", "mailer-daemon@",
		"github.com", "stripe.com", "aws.amazon.com", "google.com", "vercel.com",
		"cloudflare.com", "linear.app", "sentry.io", "atlassian.net", "notion.so",
		"figma.com", "slack.com", "zoom.us", "paypal.com", "uber.com",
	}
	for _, kw := range automatedSenders {
		if strings.Contains(senderLower, kw) {
			return string(SplitUpdates)
		}
	}

	transactionalSubjects := []string{
		"receipt", "invoice", "order confirmation", "payment received", "payment confirmation",
		"security alert", "verification code", "password reset", "one-time password",
		"statement available", "your subscription", "shipping update", "tracking number",
	}
	for _, kw := range transactionalSubjects {
		if strings.Contains(subjectLower, kw) {
			return string(SplitUpdates)
		}
	}

	// 5. Default fallback is IMPORTANT / MAIN
	return string(SplitMain)
}

