package main

import (
	"regexp"
	"strings"
)

var (
	// Known ESP and CRM tracking domains & path signatures
	trackerDomainPatterns = []string{
		`mandrillapp\.com/track`,
		`hubspot\.com/email/open`,
		`sendgrid\.net/wf/open`,
		`superhuman\.com/tracker`,
		`mailfoogae\.appspot\.com`,
		`open\.convertkit\.com`,
		`click\.pstmrk\.it`,
		`mailtrack\.io/trace`,
		`yesware\.com/trk`,
		`mixmax\.com/api/track`,
		`app\.mailjet\.com/gopen`,
		`list-manage\.com/track/open`,
		`beacon\.`,
		`pixel\.gif`,
		`pixel\.png`,
		`open\.gif`,
		`/trk\.png`,
		`/open\.php`,
	}

	// Regex to match <img> tags
	imgTagRegex = regexp.MustCompile(`(?i)<img\b[^>]*>`)

	// Regexes to extract attributes
	srcAttrRegex    = regexp.MustCompile(`(?i)\bsrc=["']?([^"'\s>]+)["']?`)
	widthAttrRegex  = regexp.MustCompile(`(?i)\bwidth=["']?(\d+)["']?`)
	heightAttrRegex = regexp.MustCompile(`(?i)\bheight=["']?(\d+)["']?`)
	styleAttrRegex  = regexp.MustCompile(`(?i)\bstyle=["']?([^"'>]+)["']?`)

	// Newsletter preheader and zero-width spacer cleaners
	zeroWidthSpacersRegex  = regexp.MustCompile(`(?i)(&zwnj;|&nbsp;|\x{200B}|\x{200C}|\x{200D}|\x{FEFF}|\s){6,}`)
	preheaderDivRegex      = regexp.MustCompile(`(?is)<(?:div|span)[^>]*style="[^"]*(?:max-height:\s*0|font-size:\s*0|line-height:\s*0|display:\s*none)[^"]*"[^>]*>.*?</(?:div|span)>`)
	multipleBrRegex        = regexp.MustCompile(`(?i)(<br\s*/?>\s*){3,}`)
	emptyParagraphRegex    = regexp.MustCompile(`(?i)<p[^>]*>(\s|&nbsp;|<br\s*/?>)*</p>`)
	emptySpacerDivRegex    = regexp.MustCompile(`(?i)<div[^>]*style="[^"]*(?:height:\s*\d+px|line-height:\s*\d+px)[^"]*"[^>]*>(\s|&nbsp;|<br\s*/?>)*</div>`)
	excessiveTablePadRegex = regexp.MustCompile(`(?i)<td[^>]*height="[4-9]\d{1,2}"[^>]*>(\s|&nbsp;|<br\s*/?>)*</td>`)
)

type SanitizeResult struct {
	CleanHTML       string
	TrackersBlocked int
}

// SanitizeEmailHTML removes tracking pixels, strips dangerous scripts, and normalizes spacer bloat
func SanitizeEmailHTML(rawHTML string) SanitizeResult {
	if strings.TrimSpace(rawHTML) == "" {
		return SanitizeResult{CleanHTML: "", TrackersBlocked: 0}
	}

	trackersCount := 0

	// 1. Process all <img> tags through the 5-stage classifier
	cleanHTML := imgTagRegex.ReplaceAllStringFunc(rawHTML, func(imgTag string) string {
		srcMatch := srcAttrRegex.FindStringSubmatch(imgTag)
		if len(srcMatch) < 2 {
			return imgTag
		}
		src := srcMatch[1]

		// Stage 1: Pass inline CID and base64 data URLs immediately (100% safe & local)
		if strings.HasPrefix(src, "cid:") || strings.HasPrefix(src, "data:image/") {
			return imgTag
		}

		// Stage 2: Geometric and visibility filters (1x1, 0x0, hidden, opacity:0)
		widthMatch := widthAttrRegex.FindStringSubmatch(imgTag)
		heightMatch := heightAttrRegex.FindStringSubmatch(imgTag)
		if len(widthMatch) >= 2 && len(heightMatch) >= 2 {
			w := widthMatch[1]
			h := heightMatch[1]
			if (w == "0" || w == "1") && (h == "0" || h == "1") {
				trackersCount++
				return `<!-- blocked tracker (1x1) -->`
			}
		}

		styleMatch := styleAttrRegex.FindStringSubmatch(imgTag)
		if len(styleMatch) >= 2 {
			style := strings.ToLower(styleMatch[1])
			if strings.Contains(style, "display:none") ||
				strings.Contains(style, "display: none") ||
				strings.Contains(style, "visibility:hidden") ||
				strings.Contains(style, "visibility: hidden") ||
				strings.Contains(style, "opacity:0") ||
				strings.Contains(style, "opacity: 0") ||
				strings.Contains(style, "max-height:0") {
				trackersCount++
				return `<!-- blocked tracker (hidden style) -->`
			}
		}

		// Stage 3: Known Tracker & Telemetry Domains / Paths
		srcLower := strings.ToLower(src)
		for _, pattern := range trackerDomainPatterns {
			matched, _ := regexp.MatchString(pattern, srcLower)
			if matched {
				trackersCount++
				return `<!-- blocked tracker (telemetry domain) -->`
			}
		}

		// Stage 4: Allowed "Good" content image
		return imgTag
	})

	// 2. Neutralize dangerous script, object, embed, or form tags
	cleanHTML = regexp.MustCompile(`(?is)<script.*?</script>`).ReplaceAllString(cleanHTML, "")
	cleanHTML = regexp.MustCompile(`(?i)<(object|embed|form|iframe)\b[^>]*>`).ReplaceAllString(cleanHTML, "")

	// 3. Clean up newsletter whitespace bloat and artificial gaps
	cleanHTML = preheaderDivRegex.ReplaceAllString(cleanHTML, "")
	cleanHTML = zeroWidthSpacersRegex.ReplaceAllString(cleanHTML, " ")
	cleanHTML = excessiveTablePadRegex.ReplaceAllString(cleanHTML, "<td style='height:8px;line-height:8px;'></td>")
	cleanHTML = emptySpacerDivRegex.ReplaceAllString(cleanHTML, "")
	cleanHTML = emptyParagraphRegex.ReplaceAllString(cleanHTML, "")
	cleanHTML = multipleBrRegex.ReplaceAllString(cleanHTML, "<br><br>")

	return SanitizeResult{
		CleanHTML:       cleanHTML,
		TrackersBlocked: trackersCount,
	}
}

sourceFiles.sanitizer_test.go:
package main

import (
	"strings"
	"testing"
)

func TestSanitizeEmailHTML(t *testing.T) {
	rawHTML := `
	<div>
		<h1>Hello World</h1>
		<!-- Safe good image -->
		<img src="https://cdn.example.com/banner.png" width="600" height="200" />
		<!-- Safe inline CID -->
		<img src="cid:logo.png@123" />
		<!-- 1x1 Tracker -->
		<img src="https://tracker.com/t.gif" width="1" height="1" />
		<!-- Hidden Tracker -->
		<img src="https://unknown.com/img.jpg" style="display:none;" />
		<!-- Telemetry Domain Tracker -->
		<img src="https://open.convertkit.com/12345/abcdef" />
		<script>alert("hacked");</script>
	</div>
	`

	result := SanitizeEmailHTML(rawHTML)

	if result.TrackersBlocked != 3 {
		t.Errorf("Expected 3 trackers blocked, got %d", result.TrackersBlocked)
	}

	if strings.Contains(result.CleanHTML, "<script>") {
		t.Errorf("Expected script tags to be stripped")
	}

	if !strings.Contains(result.CleanHTML, "https://cdn.example.com/banner.png") {
		t.Errorf("Expected legitimate content image to be preserved")
	}

	if !strings.Contains(result.CleanHTML, "cid:logo.png@123") {
		t.Errorf("Expected inline CID image to be preserved")
	}
}

