package main

import (
	"database/sql"
	"fmt"
	"strings"
	"sync"
	"time"

	_ "modernc.org/sqlite"
)

type EmailThread struct {
	ID            string `json:"id"`
	AccountEmail  string `json:"accountEmail"`
	HistoryID     string `json:"historyId"`
	Snippet       string `json:"snippet"`
	Subject       string `json:"subject"`
	From          string `json:"from"`
	InternalDate  int64  `json:"internalDate"`
	LabelIDs      string `json:"labelIds"`
	SplitCategory string `json:"splitCategory"`
}

type EmailMessage struct {
	ID              string            `json:"id"`
	AccountEmail    string            `json:"accountEmail"`
	ThreadID        string            `json:"threadId"`
	From            string            `json:"from"`
	To              string            `json:"to"`
	Date            int64             `json:"date"`
	Subject         string            `json:"subject"`
	Snippet         string            `json:"snippet"`
	BodyHTML        string            `json:"bodyHtml"`
	BodyText        string            `json:"bodyText"`
	TrackersBlocked int               `json:"trackersBlocked"`
	Attachments     []EmailAttachment `json:"attachments"`
}

type EmailAttachment struct {
	ID           string `json:"id"`
	MessageID    string `json:"messageId"`
	Filename     string `json:"filename"`
	MimeType     string `json:"mimeType"`
	Size         int64  `json:"size"`
	AttachmentID string `json:"attachmentId"`
	ContentID    string `json:"contentId"`
	LocalPath    string `json:"localPath"`
}

type LocalStore struct {
	db      *sql.DB // write connection (single conn, serialized by writeMu)
	readDB  *sql.DB // read-only connection pool for concurrent queries
	writeMu sync.Mutex
}

func NewLocalStore(dbPath string) (*LocalStore, error) {
	// Write connection: single connection to serialize writes
	db, err := sql.Open("sqlite", dbPath+"?_pragma=journal_mode(WAL)&_pragma=synchronous(NORMAL)&_pragma=busy_timeout(10000)&_pragma=cache_size(-64000)")
	if err != nil {
		return nil, fmt.Errorf("failed to open database: %w", err)
	}
	db.SetMaxOpenConns(1) // Single writer prevents lock collisions

	// Read connection pool: separate connections so reads never block behind writes (WAL mode allows this)
	readDB, err := sql.Open("sqlite", dbPath+"?_pragma=journal_mode(WAL)&_pragma=synchronous(NORMAL)&_pragma=busy_timeout(5000)&_pragma=cache_size(-64000)&_pragma=query_only(1)")
	if err != nil {
		return nil, fmt.Errorf("failed to open read database: %w", err)
	}
	readDB.SetMaxOpenConns(4) // Allow multiple concurrent readers

	// Core tables
	baseSchema := `
	CREATE TABLE IF NOT EXISTS threads (
		id TEXT PRIMARY KEY,
		account_email TEXT DEFAULT '',
		history_id TEXT,
		snippet TEXT,
		subject TEXT,
		sender TEXT,
		internal_date INTEGER,
		label_ids TEXT,
		split_category TEXT DEFAULT 'MAIN'
	);

	CREATE TABLE IF NOT EXISTS messages (
		id TEXT PRIMARY KEY,
		account_email TEXT DEFAULT '',
		thread_id TEXT,
		sender TEXT,
		recipient TEXT,
		internal_date INTEGER,
		subject TEXT,
		snippet TEXT,
		body_html TEXT,
		body_text TEXT,
		trackers_blocked INTEGER DEFAULT 0,
		FOREIGN KEY(thread_id) REFERENCES threads(id)
	);

	CREATE TABLE IF NOT EXISTS attachments (
		id TEXT PRIMARY KEY,
		message_id TEXT,
		filename TEXT,
		mime_type TEXT,
		size_bytes INTEGER,
		attachment_id TEXT,
		content_id TEXT,
		local_path TEXT,
		FOREIGN KEY(message_id) REFERENCES messages(id)
	);

	CREATE TABLE IF NOT EXISTS sync_state (
		account_email TEXT PRIMARY KEY,
		last_history_id TEXT,
		backfill_page_token TEXT DEFAULT '',
		last_synced_at INTEGER
	);

	CREATE TABLE IF NOT EXISTS split_inboxes (
		id TEXT PRIMARY KEY,
		name TEXT NOT NULL,
		shortcut_key TEXT DEFAULT '',
		filter_type TEXT DEFAULT 'CATEGORY',
		filter_value TEXT NOT NULL,
		is_system INTEGER DEFAULT 0,
		sort_order INTEGER DEFAULT 0
	);

	CREATE VIRTUAL TABLE IF NOT EXISTS thread_search USING fts5(
		thread_id UNINDEXED,
		subject,
		sender,
		snippet
	);
	`

	if _, err := db.Exec(baseSchema); err != nil {
		return nil, fmt.Errorf("failed to init schema: %w", err)
	}

	// Migrations for existing databases
	_, _ = db.Exec("ALTER TABLE threads ADD COLUMN account_email TEXT DEFAULT '';")
	_, _ = db.Exec("ALTER TABLE messages ADD COLUMN account_email TEXT DEFAULT '';")
	_, _ = db.Exec("ALTER TABLE threads ADD COLUMN split_category TEXT DEFAULT 'MAIN';")
	_, _ = db.Exec("ALTER TABLE sync_state ADD COLUMN backfill_page_token TEXT DEFAULT '';")

	// Triggers and indexes after columns exist
	auxSchema := `
	-- Triggers to keep FTS5 synchronized automatically with threads table
	CREATE TRIGGER IF NOT EXISTS threads_ai AFTER INSERT ON threads BEGIN
		INSERT INTO thread_search(thread_id, subject, sender, snippet)
		VALUES (new.id, new.subject, new.sender, new.snippet);
	END;

	CREATE TRIGGER IF NOT EXISTS threads_ad AFTER DELETE ON threads BEGIN
		DELETE FROM thread_search WHERE thread_id = old.id;
	END;

	CREATE TRIGGER IF NOT EXISTS threads_au AFTER UPDATE ON threads BEGIN
		DELETE FROM thread_search WHERE thread_id = old.id;
		INSERT INTO thread_search(thread_id, subject, sender, snippet)
		VALUES (new.id, new.subject, new.sender, new.snippet);
	END;

	-- Fast composite B-Tree indexes for instant inbox and split switching
	CREATE INDEX IF NOT EXISTS idx_threads_acc_date ON threads(account_email, internal_date DESC);
	CREATE INDEX IF NOT EXISTS idx_threads_date ON threads(internal_date DESC);
	CREATE INDEX IF NOT EXISTS idx_threads_split_date ON threads(account_email, split_category, internal_date DESC);
	CREATE INDEX IF NOT EXISTS idx_threads_split ON threads(split_category, internal_date DESC);
	CREATE INDEX IF NOT EXISTS idx_messages_thread_date ON messages(thread_id, internal_date ASC);
	`

	if _, err := db.Exec(auxSchema); err != nil {
		return nil, fmt.Errorf("failed to init indexes: %w", err)
	}

	// Seed default split inboxes if none exist
	seedDefaultSplits(db)

	// Backfill any legacy blank account_email records to the primary email
	_, _ = db.Exec(`
		UPDATE threads SET account_email = (
			SELECT account_email FROM threads WHERE account_email != '' AND account_email IS NOT NULL LIMIT 1
		) WHERE account_email = '' OR account_email IS NULL;
	`)

	// Backfill existing threads into FTS5 index if any exist
	_, _ = db.Exec(`
		INSERT OR IGNORE INTO thread_search(thread_id, subject, sender, snippet)
		SELECT id, subject, sender, snippet FROM threads
		WHERE id NOT IN (SELECT thread_id FROM thread_search);
	`)

	store := &LocalStore{db: db, readDB: readDB}

	// Asynchronously backfill split categories for existing threads if unclassified
	go store.backfillSplitCategories()

	return store, nil
}

func seedDefaultSplits(db *sql.DB) {
	var count int
	_ = db.QueryRow("SELECT count(*) FROM split_inboxes").Scan(&count)
	if count == 0 {
		splits := []struct {
			id, name, shortcut, filterType, filterValue string
			isSystem, sortOrder                         int
		}{
			{"important", "Important", "1", "CATEGORY", "MAIN", 1, 1},
			{"newsletters", "Newsletters", "2", "CATEGORY", "NEWSLETTERS", 1, 2},
			{"updates", "Updates", "3", "CATEGORY", "UPDATES", 1, 3},
			{"social", "Social", "4", "CATEGORY", "SOCIAL", 1, 4},
			{"all", "All Mail", "5", "CATEGORY", "ALL", 1, 5},
		}

		for _, s := range splits {
			_, _ = db.Exec(`
				INSERT OR IGNORE INTO split_inboxes (id, name, shortcut_key, filter_type, filter_value, is_system, sort_order)
				VALUES (?, ?, ?, ?, ?, ?, ?);`,
				s.id, s.name, s.shortcut, s.filterType, s.filterValue, s.isSystem, s.sortOrder,
			)
		}
	}
}

func (s *LocalStore) GetSplitInboxes() ([]SplitInboxDef, error) {
	query := `SELECT id, name, shortcut_key, filter_type, filter_value, is_system, sort_order FROM split_inboxes ORDER BY sort_order ASC, name ASC`
	rows, err := s.readDB.Query(query)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var list []SplitInboxDef
	for rows.Next() {
		var sp SplitInboxDef
		var isSys int
		if err := rows.Scan(&sp.ID, &sp.Name, &sp.ShortcutKey, &sp.FilterType, &sp.FilterValue, &isSys, &sp.SortOrder); err == nil {
			sp.IsSystem = (isSys == 1)
			list = append(list, sp)
		}
	}
	return list, nil
}

func (s *LocalStore) SaveSplitInbox(sp SplitInboxDef) error {
	isSys := 0
	if sp.IsSystem {
		isSys = 1
	}
	query := `
	INSERT INTO split_inboxes (id, name, shortcut_key, filter_type, filter_value, is_system, sort_order)
	VALUES (?, ?, ?, ?, ?, ?, ?)
	ON CONFLICT(id) DO UPDATE SET
		name = excluded.name,
		shortcut_key = excluded.shortcut_key,
		filter_type = excluded.filter_type,
		filter_value = excluded.filter_value,
		sort_order = excluded.sort_order;`

	s.writeMu.Lock()
	defer s.writeMu.Unlock()

	_, err := s.db.Exec(query, sp.ID, sp.Name, sp.ShortcutKey, sp.FilterType, sp.FilterValue, isSys, sp.SortOrder)
	if err != nil {
		return err
	}

	// Immediately re-categorize existing matching threads to this new split
	if !sp.IsSystem && sp.FilterValue != "" {
		likePat := "%" + sp.FilterValue + "%"
		_, _ = s.db.Exec(`
			UPDATE threads 
			SET split_category = ? 
			WHERE subject LIKE ? OR sender LIKE ? OR snippet LIKE ?;`,
			sp.ID, likePat, likePat, likePat,
		)
	}

	return nil
}

func (s *LocalStore) DeleteSplitInbox(id string) error {
	s.writeMu.Lock()
	defer s.writeMu.Unlock()

	_, err := s.db.Exec("DELETE FROM split_inboxes WHERE id = ? AND is_system = 0", id)
	if err != nil {
		return err
	}

	// Reset threads with this category back to MAIN so they don't get orphaned
	_, _ = s.db.Exec("UPDATE threads SET split_category = 'MAIN' WHERE split_category = ?", id)
	return nil
}

func (s *LocalStore) backfillSplitCategories() {
	time.Sleep(200 * time.Millisecond) // Let startup queries finish first

	customSplits, _ := s.GetSplitInboxes()

	rows, err := s.db.Query("SELECT id, label_ids, sender, subject, snippet, split_category FROM threads LIMIT 50000")
	if err != nil {
		return
	}

	type item struct {
		id, cat string
	}
	var updates []item

	for rows.Next() {
		var id, labelIDs, sender, subject, snippet, currentCat string
		if err := rows.Scan(&id, &labelIDs, &sender, &subject, &snippet, &currentCat); err == nil {
			cat := ClassifyThreadWithRules(strings.Split(labelIDs, ","), sender, subject, snippet, customSplits)
			if cat != currentCat {
				updates = append(updates, item{id: id, cat: cat})
			}
		}
	}
	rows.Close()

	if len(updates) == 0 {
		return
	}

	// Update in micro-batches of 100 items with writeMu and sleeps to yield to user operations
	chunkSize := 100
	for i := 0; i < len(updates); i += chunkSize {
		end := i + chunkSize
		if end > len(updates) {
			end = len(updates)
		}
		chunk := updates[i:end]

		s.writeMu.Lock()
		tx, err := s.db.Begin()
		if err == nil {
			stmt, err := tx.Prepare("UPDATE threads SET split_category = ? WHERE id = ?")
			if err == nil {
				for _, u := range chunk {
					_, _ = stmt.Exec(u.cat, u.id)
				}
				stmt.Close()
			}
			_ = tx.Commit()
		}
		s.writeMu.Unlock()

		time.Sleep(5 * time.Millisecond) // Yield database lock
	}
}

func (s *LocalStore) GetLastHistoryID(accountEmail string) (string, error) {
	var historyID string
	err := s.db.QueryRow("SELECT last_history_id FROM sync_state WHERE account_email = ?", accountEmail).Scan(&historyID)
	if err == nil && historyID != "" {
		return historyID, nil
	}

	var maxHist sql.NullString
	if accountEmail == "" || accountEmail == "ALL" {
		_ = s.db.QueryRow("SELECT history_id FROM threads ORDER BY internal_date DESC LIMIT 1").Scan(&maxHist)
	} else {
		_ = s.db.QueryRow("SELECT history_id FROM threads WHERE account_email = ? ORDER BY internal_date DESC LIMIT 1", accountEmail).Scan(&maxHist)
	}

	if maxHist.Valid && maxHist.String != "" {
		_ = s.SetLastHistoryID(accountEmail, maxHist.String)
		return maxHist.String, nil
	}

	return "", nil
}

