// FilterMissingThreadIDs returns only the IDs from threadIDs that are NOT already in SQLite threads table
func (s *LocalStore) FilterMissingThreadIDs(threadIDs []string) ([]string, error) {
	if len(threadIDs) == 0 {
		return []string{}, nil
	}

	// Prepare placeholder string ?,?,?
	placeholders := make([]string, len(threadIDs))
	args := make([]interface{}, len(threadIDs))
	for i, id := range threadIDs {
		placeholders[i] = "?"
		args[i] = id
	}

	query := fmt.Sprintf("SELECT id FROM threads WHERE id IN (%s)", strings.Join(placeholders, ","))
	rows, err := s.readDB.Query(query, args...)
	if err != nil {
		return threadIDs, err
	}
	defer rows.Close()

	existing := make(map[string]bool)
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err == nil {
			existing[id] = true
		}
	}

	var missing []string
	for _, id := range threadIDs {
		if !existing[id] {
			missing = append(missing, id)
		}
	}
	return missing, nil
}

func (s *LocalStore) SetLastHistoryID(accountEmail, historyID string) error {
