	VALUES (?, ?, ?)
	ON CONFLICT(account_email) DO UPDATE SET
		last_history_id = excluded.last_history_id,
		last_synced_at = excluded.last_synced_at;`

	_, err := s.db.Exec(query, accountEmail, historyID, time.Now().Unix())
	return err
}

func (s *LocalStore) BatchUpsertThreads(threads []EmailThread) error {
	if len(threads) == 0 {
		return nil
	}

	customSplits, _ := s.GetSplitInboxes()

	s.writeMu.Lock()
	defer s.writeMu.Unlock()

	tx, err := s.db.Begin()
	if err != nil {
		return err
	}
	defer tx.Rollback()

	stmt, err := tx.Prepare(`
	INSERT INTO threads (id, account_email, history_id, snippet, subject, sender, internal_date, label_ids, split_category)
	VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
	ON CONFLICT(id) DO UPDATE SET
		account_email = excluded.account_email,
		snippet = excluded.snippet,
		subject = excluded.subject,
		sender = excluded.sender,
		label_ids = excluded.label_ids,
		split_category = excluded.split_category;`)
	if err != nil {
		return err
	}
	defer stmt.Close()

	for _, t := range threads {
		cat := t.SplitCategory
		if cat == "" {
			cat = ClassifyThreadWithRules(strings.Split(t.LabelIDs, ","), t.From, t.Subject, t.Snippet, customSplits)
		}
		if _, err := stmt.Exec(t.ID, t.AccountEmail, t.HistoryID, t.Snippet, t.Subject, t.From, t.InternalDate, t.LabelIDs, cat); err != nil {
			return err
		}
	}

	return tx.Commit()
}

func (s *LocalStore) UpsertThread(t EmailThread) error {
	return s.BatchUpsertThreads([]EmailThread{t})
}

func (s *LocalStore) GetSplitCounts(accountFilter string) (map[string]int, error) {
	counts := map[string]int{
		"MAIN":        0,
		"NEWSLETTERS": 0,
		"UPDATES":     0,
		"SOCIAL":      0,
		"ALL":         0,
	}

	accClause := ""
	var args []interface{}
	if accountFilter != "" && accountFilter != "ALL" {
		accClause = " WHERE account_email = ?"
		args = append(args, accountFilter)
	}

	// 1. Total All Mail count
	var total int
	_ = s.readDB.QueryRow("SELECT count(*) FROM threads"+accClause, args...).Scan(&total)
	counts["ALL"] = total

	// 2. Newsletters count
	newsClause := " WHERE (split_category = 'NEWSLETTERS' OR sender LIKE '%newsletter%' OR sender LIKE '%substack%' OR sender LIKE '%seeking alpha%' OR sender LIKE '%beehiiv%' OR sender LIKE '%medium.com%' OR snippet LIKE '%unsubscribe%' OR snippet LIKE '%view in browser%')"
	if accClause != "" {
		newsClause += " AND account_email = ?"
	}
	var newsCnt int
	_ = s.readDB.QueryRow("SELECT count(*) FROM threads"+newsClause, args...).Scan(&newsCnt)
	counts["NEWSLETTERS"] = newsCnt

	// 3. Updates count
	updClause := " WHERE (split_category = 'UPDATES' OR sender LIKE '%noreply%' OR sender LIKE '%no-reply%' OR sender LIKE '%notifications%' OR sender LIKE '%billing%' OR sender LIKE '%receipt%' OR sender LIKE '%github.com%' OR sender LIKE '%stripe.com%' OR subject LIKE '%invoice%' OR subject LIKE '%receipt%')"
	if accClause != "" {
		updClause += " AND account_email = ?"
	}
	var updCnt int
	_ = s.readDB.QueryRow("SELECT count(*) FROM threads"+updClause, args...).Scan(&updCnt)
	counts["UPDATES"] = updCnt

	// 4. Social count
	socClause := " WHERE (split_category = 'SOCIAL' OR sender LIKE '%linkedin%' OR sender LIKE '%twitter%' OR sender LIKE '%x.com%' OR sender LIKE '%discord%' OR sender LIKE '%facebook%')"
	if accClause != "" {
		socClause += " AND account_email = ?"
	}
	var socCnt int
	_ = s.readDB.QueryRow("SELECT count(*) FROM threads"+socClause, args...).Scan(&socCnt)
	counts["SOCIAL"] = socCnt

	// 5. Important (Main) count
	mainCnt := total - newsCnt - updCnt - socCnt
	if mainCnt < 0 {
		mainCnt = 0
	}
	counts["MAIN"] = mainCnt

	// 6. Custom splits counts
	splits, _ := s.GetSplitInboxes()
	for _, sp := range splits {
		if sp.FilterType == "QUERY" && sp.FilterValue != "" {
			var cnt int
			likePat := "%" + sp.FilterValue + "%"
			if accClause == "" {
				_ = s.readDB.QueryRow("SELECT count(*) FROM threads WHERE split_category = ? OR subject LIKE ? OR sender LIKE ? OR snippet LIKE ?", sp.ID, likePat, likePat, likePat).Scan(&cnt)
			} else {
				_ = s.readDB.QueryRow("SELECT count(*) FROM threads WHERE account_email = ? AND (split_category = ? OR subject LIKE ? OR sender LIKE ? OR snippet LIKE ?)", accountFilter, sp.ID, likePat, likePat, likePat).Scan(&cnt)
			}
			counts[sp.ID] = cnt
			counts[sp.FilterValue] = cnt
		}
	}

	return counts, nil
}

func (s *LocalStore) GetInboxThreads(accountFilter, splitFilter string, limit, offset int) ([]EmailThread, error) {
	if limit <= 0 {
		limit = 100
	}

	isAllAccounts := (accountFilter == "" || accountFilter == "ALL")
	isAllSplits := (splitFilter == "" || splitFilter == "ALL" || splitFilter == "all")

	if isAllSplits {
		var query string
		var rows *sql.Rows
		var err error
		if isAllAccounts {
			query = "SELECT id, account_email, history_id, snippet, subject, sender, internal_date, label_ids, split_category FROM threads ORDER BY internal_date DESC LIMIT ? OFFSET ?"
			rows, err = s.readDB.Query(query, limit, offset)
		} else {
			query = "SELECT id, account_email, history_id, snippet, subject, sender, internal_date, label_ids, split_category FROM threads WHERE account_email = ? ORDER BY internal_date DESC LIMIT ? OFFSET ?"
			rows, err = s.readDB.Query(query, accountFilter, limit, offset)
		}
		if err != nil {
			return nil, err
		}
		defer rows.Close()

		var threads []EmailThread
		for rows.Next() {
			var t EmailThread
			if err := rows.Scan(&t.ID, &t.AccountEmail, &t.HistoryID, &t.Snippet, &t.Subject, &t.From, &t.InternalDate, &t.LabelIDs, &t.SplitCategory); err == nil {
				threads = append(threads, t)
			}
		}
		return threads, nil
	}

	// Resolve split category or custom query
	filterValue := splitFilter

	if splitFilter == "important" || splitFilter == "MAIN" {
		filterValue = "MAIN"
	} else if splitFilter == "newsletters" || splitFilter == "NEWSLETTERS" {
		filterValue = "NEWSLETTERS"
	} else if splitFilter == "updates" || splitFilter == "UPDATES" {
		filterValue = "UPDATES"
	} else if splitFilter == "social" || splitFilter == "SOCIAL" {
		filterValue = "SOCIAL"
	} else {
		var dbVal string
		err := s.readDB.QueryRow("SELECT filter_value FROM split_inboxes WHERE id = ?", splitFilter).Scan(&dbVal)
		if err == nil && dbVal != "" {
			filterValue = dbVal
		}
	}

	var whereClause string
	var params []interface{}

	switch filterValue {
	case "NEWSLETTERS":
		whereClause = "(split_category = 'NEWSLETTERS' OR sender LIKE '%newsletter%' OR sender LIKE '%substack%' OR sender LIKE '%seeking alpha%' OR sender LIKE '%beehiiv%' OR sender LIKE '%medium.com%' OR snippet LIKE '%unsubscribe%' OR snippet LIKE '%view in browser%')"
	case "UPDATES":
		whereClause = "(split_category = 'UPDATES' OR sender LIKE '%noreply%' OR sender LIKE '%no-reply%' OR sender LIKE '%notifications%' OR sender LIKE '%billing%' OR sender LIKE '%receipt%' OR sender LIKE '%github.com%' OR sender LIKE '%stripe.com%' OR subject LIKE '%invoice%' OR subject LIKE '%receipt%')"
	case "SOCIAL":
		whereClause = "(split_category = 'SOCIAL' OR sender LIKE '%linkedin%' OR sender LIKE '%twitter%' OR sender LIKE '%x.com%' OR sender LIKE '%discord%' OR sender LIKE '%facebook%')"
	case "MAIN":
		// Direct personal/work threads excluding automated newsletters and updates
		whereClause = "(split_category = 'MAIN' OR (sender NOT LIKE '%newsletter%' AND sender NOT LIKE '%substack%' AND sender NOT LIKE '%noreply%' AND sender NOT LIKE '%no-reply%' AND sender NOT LIKE '%notifications%' AND sender NOT LIKE '%billing%' AND snippet NOT LIKE '%unsubscribe%'))"
	default:
		// Custom split query or ID
		likePat := "%" + filterValue + "%"
		whereClause = "(split_category = ? OR subject LIKE ? OR sender LIKE ? OR snippet LIKE ?)"
		params = append(params, splitFilter, likePat, likePat, likePat)
	}

	if !isAllAccounts {
		whereClause = "account_email = ? AND " + whereClause
		params = append([]interface{}{accountFilter}, params...)
	}

	query := fmt.Sprintf(`
		SELECT id, account_email, history_id, snippet, subject, sender, internal_date, label_ids, split_category 
		FROM threads 
		WHERE %s 
		ORDER BY internal_date DESC LIMIT ? OFFSET ?`, whereClause)

	params = append(params, limit, offset)

	rows, err := s.readDB.Query(query, params...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var threads []EmailThread
	for rows.Next() {
		var t EmailThread
		if err := rows.Scan(&t.ID, &t.AccountEmail, &t.HistoryID, &t.Snippet, &t.Subject, &t.From, &t.InternalDate, &t.LabelIDs, &t.SplitCategory); err == nil {
			threads = append(threads, t)
		}
	}
	return threads, nil
}

func (s *LocalStore) SearchThreads(query, accountFilter, splitFilter string) ([]EmailThread, error) {
	cleanQuery := strings.TrimSpace(query)
	if cleanQuery == "" {
		return s.GetInboxThreads(accountFilter, splitFilter, 100, 0)
	}

	words := strings.Fields(cleanQuery)
	var formattedWords []string
	for _, w := range words {
		w = strings.Map(func(r rune) rune {
			if strings.ContainsRune(`"':*^`, r) {
				return -1
			}
			return r
		}, w)
		if w != "" {
			formattedWords = append(formattedWords, fmt.Sprintf(`"%s"*`, w))
		}
	}

	ftsQuery := strings.Join(formattedWords, " ")
	if ftsQuery == "" {
		return s.GetInboxThreads(accountFilter, splitFilter, 100, 0)
	}

	isAllAccounts := (accountFilter == "" || accountFilter == "ALL")
	isAllSplits := (splitFilter == "" || splitFilter == "ALL" || splitFilter == "all")

	categoryValue := splitFilter
	if splitFilter == "important" || splitFilter == "MAIN" {
		categoryValue = "MAIN"
	} else if splitFilter == "newsletters" || splitFilter == "NEWSLETTERS" {
		categoryValue = "NEWSLETTERS"
	} else if splitFilter == "updates" || splitFilter == "UPDATES" {
		categoryValue = "UPDATES"
	} else if splitFilter == "social" || splitFilter == "SOCIAL" {
		categoryValue = "SOCIAL"
	}

	var sqlQuery string
	var rows *sql.Rows
	var err error

	if isAllAccounts && isAllSplits {
		sqlQuery = `
		SELECT t.id, t.account_email, t.history_id, t.snippet, t.subject, t.sender, t.internal_date, t.label_ids, t.split_category 
		FROM threads t
		JOIN thread_search s ON t.id = s.thread_id
		WHERE thread_search MATCH ?
		ORDER BY t.internal_date DESC LIMIT 100;`
		rows, err = s.readDB.Query(sqlQuery, ftsQuery)
	} else if isAllAccounts && !isAllSplits {
		sqlQuery = `
		SELECT t.id, t.account_email, t.history_id, t.snippet, t.subject, t.sender, t.internal_date, t.label_ids, t.split_category 
		FROM threads t
		JOIN thread_search s ON t.id = s.thread_id
		WHERE thread_search MATCH ? AND t.split_category = ?
		ORDER BY t.internal_date DESC LIMIT 100;`
		rows, err = s.readDB.Query(sqlQuery, ftsQuery, categoryValue)
	} else if !isAllAccounts && isAllSplits {
		sqlQuery = `
		SELECT t.id, t.account_email, t.history_id, t.snippet, t.subject, t.sender, t.internal_date, t.label_ids, t.split_category 
		FROM threads t
		JOIN thread_search s ON t.id = s.thread_id
		WHERE thread_search MATCH ? AND t.account_email = ?
		ORDER BY t.internal_date DESC LIMIT 100;`
		rows, err = s.readDB.Query(sqlQuery, ftsQuery, accountFilter)
	} else {
		sqlQuery = `
		SELECT t.id, t.account_email, t.history_id, t.snippet, t.subject, t.sender, t.internal_date, t.label_ids, t.split_category 
		FROM threads t
		JOIN thread_search s ON t.id = s.thread_id
		WHERE thread_search MATCH ? AND t.account_email = ? AND t.split_category = ?
		ORDER BY t.internal_date DESC LIMIT 100;`
		rows, err = s.readDB.Query(sqlQuery, ftsQuery, accountFilter, categoryValue)
	}

	if err != nil {
		likePattern := "%" + cleanQuery + "%"
		rows, err = s.readDB.Query(`
			SELECT id, account_email, history_id, snippet, subject, sender, internal_date, label_ids, split_category
			FROM threads
			WHERE subject LIKE ? OR sender LIKE ? OR snippet LIKE ?
			ORDER BY internal_date DESC LIMIT 100;`, likePattern, likePattern, likePattern)
		if err != nil {
			return nil, err
		}
	}
	defer rows.Close()

	var threads []EmailThread
	for rows.Next() {
		var t EmailThread
		if err := rows.Scan(&t.ID, &t.AccountEmail, &t.HistoryID, &t.Snippet, &t.Subject, &t.From, &t.InternalDate, &t.LabelIDs, &t.SplitCategory); err != nil {
			return nil, err
		}
		threads = append(threads, t)
	}
	return threads, nil
}

func (s *LocalStore) UpsertMessage(m EmailMessage) error {
	s.writeMu.Lock()
	defer s.writeMu.Unlock()

	query := `
	INSERT INTO messages (id, account_email, thread_id, sender, recipient, internal_date, subject, snippet, body_html, body_text, trackers_blocked)
	VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
	ON CONFLICT(id) DO UPDATE SET
		account_email = excluded.account_email,
		snippet = excluded.snippet,
		body_html = excluded.body_html,
		body_text = excluded.body_text,
		trackers_blocked = excluded.trackers_blocked;`

	_, err := s.db.Exec(query, m.ID, m.AccountEmail, m.ThreadID, m.From, m.To, m.Date, m.Subject, m.Snippet, m.BodyHTML, m.BodyText, m.TrackersBlocked)
	return err
}

