package main

import (
	"path/filepath"
	"testing"
	"time"
)

func TestBatchUpsertThreadsDeadlock(t *testing.T) {
	tempDir := t.TempDir()
	dbPath := filepath.Join(tempDir, "test.db")

	store, err := NewLocalStore(dbPath)
	if err != nil {
		t.Fatalf("Failed to create LocalStore: %v", err)
	}

	done := make(chan error, 1)
	go func() {
		err := store.BatchUpsertThreads([]EmailThread{
			{
				ID:           "thread_1",
				AccountEmail: "test@example.com",
				Subject:      "Test Subject",
				From:         "sender@example.com",
				Snippet:      "Test snippet",
			},
		})
		done <- err
	}()

	select {
	case err := <-done:
		if err != nil {
			t.Fatalf("BatchUpsertThreads returned error: %v", err)
		}
	case <-time.After(2 * time.Second):
		t.Fatal("DEADLOCK DETECTED: BatchUpsertThreads hung and failed to complete within 2 seconds!")
	}
}

func TestGetInboxThreadsSplits(t *testing.T) {
	tempDir := t.TempDir()
	dbPath := filepath.Join(tempDir, "test.db")

	store, err := NewLocalStore(dbPath)
	if err != nil {
		t.Fatalf("Failed to create LocalStore: %v", err)
	}

	threads := []EmailThread{
		{
			ID:           "thread_main",
			AccountEmail: "user@example.com",
			Subject:      "Urgent project review",
			From:         "boss@company.com",
			Snippet:      "Please check this ASAP",
			InternalDate: 1000,
		},
		{
			ID:           "thread_news",
			AccountEmail: "user@example.com",
			Subject:      "Weekly Tech Newsletter #42",
			From:         "newsletter@substack.com",
			Snippet:      "Click here to unsubscribe",
			InternalDate: 2000,
		},
		{
			ID:           "thread_updates",
			AccountEmail: "user@example.com",
			Subject:      "Invoice #9821 payment received",
			From:         "billing@stripe.com",
			Snippet:      "Your receipt is attached",
			InternalDate: 3000,
		},
	}

	if err := store.BatchUpsertThreads(threads); err != nil {
		t.Fatalf("BatchUpsertThreads failed: %v", err)
	}

	// 1. Query "newsletters"
	newsThreads, err := store.GetInboxThreads("ALL", "newsletters", 100, 0)
	if err != nil {
		t.Fatalf("GetInboxThreads for newsletters failed: %v", err)
	}
	if len(newsThreads) != 1 || newsThreads[0].ID != "thread_news" {
		t.Errorf("Expected 1 newsletter thread (thread_news), got %d: %+v", len(newsThreads), newsThreads)
	}

	// 2. Query "updates"
	updThreads, err := store.GetInboxThreads("ALL", "updates", 100, 0)
	if err != nil {
		t.Fatalf("GetInboxThreads for updates failed: %v", err)
	}
	if len(updThreads) != 1 || updThreads[0].ID != "thread_updates" {
		t.Errorf("Expected 1 updates thread (thread_updates), got %d: %+v", len(updThreads), updThreads)
	}

	// 3. Query "important" / "MAIN"
	mainThreads, err := store.GetInboxThreads("ALL", "important", 100, 0)
	if err != nil {
		t.Fatalf("GetInboxThreads for important failed: %v", err)
	}
	if len(mainThreads) != 1 || mainThreads[0].ID != "thread_main" {
		t.Errorf("Expected 1 main thread (thread_main), got %d: %+v", len(mainThreads), mainThreads)
	}

	// 4. Query "ALL"
	allThreads, err := store.GetInboxThreads("ALL", "all", 100, 0)
	if err != nil {
		t.Fatalf("GetInboxThreads for all failed: %v", err)
	}
	if len(allThreads) != 3 {
		t.Errorf("Expected 3 total threads for all, got %d", len(allThreads))
	}
}

