package main

import (
	"context"
	"encoding/base64"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"

	"google.golang.org/api/gmail/v1"
)

type SyncEngine struct {
	srv   *gmail.Service
	store *LocalStore
}

func NewSyncEngine(srv *gmail.Service, store *LocalStore) *SyncEngine {
	return &SyncEngine{srv: srv, store: store}
}

func (s *SyncEngine) SetService(srv *gmail.Service) {
	s.srv = srv
}

// SyncAllInbox fetches ALL inbox threads across all pages for a specific account
func (s *SyncEngine) SyncAllInbox(
	ctx context.Context,
	accountEmail string,
	logger func(level, msg string),
	onProgress func(fetched, total, remaining int),
) error {
	if s.srv == nil {
		return fmt.Errorf("gmail service is not initialized")
	}

	if logger != nil {
		logger("INFO", fmt.Sprintf("[%s] Querying Gmail label statistics for INBOX...", accountEmail))
	}

	totalThreads := 0
	inboxLabel, err := s.srv.Users.Labels.Get("me", "INBOX").Context(ctx).Do()
	if err == nil && inboxLabel != nil {
		totalThreads = int(inboxLabel.ThreadsTotal)
		if logger != nil {
			logger("INFO", fmt.Sprintf("[%s] Gmail reports %d total threads (%d unread) in INBOX", accountEmail, inboxLabel.ThreadsTotal, inboxLabel.ThreadsUnread))
		}
	} else if logger != nil {
		logger("WARN", fmt.Sprintf("[%s] Could not fetch label stats: %v", accountEmail, err))
	}

	pageToken, _ := s.store.GetBackfillPageToken(accountEmail)
	if pageToken != "" && logger != nil {
		logger("INFO", fmt.Sprintf("[%s] Resuming historical sync from saved pageToken: %s...", accountEmail, pageToken[:min(len(pageToken), 12)]))
	}

	totalFetched := 0
	batchNum := 0
	workers := 12

	for {
		batchNum++
		if logger != nil {
			logger("INFO", fmt.Sprintf("[%s] Fetching thread batch #%d from Gmail API...", accountEmail, batchNum))
		}

		call := s.srv.Users.Threads.List("me").LabelIds("INBOX").MaxResults(100)
		if pageToken != "" {
			call = call.PageToken(pageToken)
		}

		startTime := time.Now()
		resp, err := call.Context(ctx).Do()
		if err != nil {
			if logger != nil {
				logger("ERROR", fmt.Sprintf("[%s] Failed to list threads on page %d: %v", accountEmail, batchNum, err))
			}
			return fmt.Errorf("failed to list threads: %w", err)
		}

		if totalThreads == 0 && resp.ResultSizeEstimate > 0 {
			totalThreads = int(resp.ResultSizeEstimate)
		}

		if len(resp.Threads) == 0 {
			if logger != nil {
				logger("INFO", fmt.Sprintf("[%s] Sync reached the end of mailbox.", accountEmail))
			}
			_ = s.store.SetBackfillPageToken(accountEmail, "")
			break
		}

		// Extract thread IDs from list response
		var pageThreadIDs []string
		for _, t := range resp.Threads {
			pageThreadIDs = append(pageThreadIDs, t.Id)
		}

		// Fast local filter: only fetch details for thread IDs NOT already cached
		missingIDs, err := s.store.FilterMissingThreadIDs(pageThreadIDs)
		if err != nil {
			missingIDs = pageThreadIDs
		}

		skippedCount := len(pageThreadIDs) - len(missingIDs)
		if logger != nil {
			if skippedCount > 0 {
				logger("INFO", fmt.Sprintf("[%s] Batch #%d: %d thread IDs already cached in SQLite (skipped %d API calls), fetching %d new threads...", accountEmail, batchNum, skippedCount, skippedCount, len(missingIDs)))
			} else {
				logger("INFO", fmt.Sprintf("[%s] Received %d thread IDs in %v. Spawning parallel workers...", accountEmail, len(resp.Threads), time.Since(startTime).Round(time.Millisecond)))
			}
		}

		var batchRecords []EmailThread
		if len(missingIDs) > 0 {
			threadChan := make(chan string, len(missingIDs))
			for _, id := range missingIDs {
				threadChan <- id
			}
			close(threadChan)

			var mu sync.Mutex
			var wg sync.WaitGroup
			numWorkers := workers
			if len(missingIDs) < numWorkers {
				numWorkers = len(missingIDs)
			}
			for i := 0; i < numWorkers; i++ {
				wg.Add(1)
				go func() {
					defer wg.Done()
					for threadID := range threadChan {
						record := s.fetchThreadSummary(ctx, threadID, accountEmail)
						if record != nil {
							mu.Lock()
							batchRecords = append(batchRecords, *record)
							mu.Unlock()
						}
					}
				}()
			}
			wg.Wait()

			// Fast single-transaction write into SQLite
			_ = s.store.BatchUpsertThreads(batchRecords)
		}

		// Checkpoint the newest historyId on Batch 1 if not set yet
		if pageToken == "" && len(batchRecords) > 0 {
			_ = s.store.SetLastHistoryID(accountEmail, batchRecords[0].HistoryID)
			if logger != nil {
				logger("INFO", fmt.Sprintf("[%s] Checkpointed latest historyId=%s into SQLite sync_state", accountEmail, batchRecords[0].HistoryID))
			}
		}

		totalFetched += len(resp.Threads)
		remaining := totalThreads - totalFetched
		if remaining < 0 {
			remaining = 0
		}

		// Save current page token progress to SQLite
		if resp.NextPageToken != "" {
			_ = s.store.SetBackfillPageToken(accountEmail, resp.NextPageToken)
		} else {
			_ = s.store.SetBackfillPageToken(accountEmail, "")
		}

		if logger != nil {
			logger("INFO", fmt.Sprintf("[%s] Batch #%d complete (%d downloaded, %d skipped). Total processed: %d / %d", accountEmail, batchNum, len(batchRecords), skippedCount, totalFetched, totalThreads))
		}

		if onProgress != nil {
			onProgress(totalFetched, totalThreads, remaining)
		}

		if resp.NextPageToken == "" {
			if logger != nil {
				logger("INFO", fmt.Sprintf("[%s] Full historical sync complete! All pages retrieved.", accountEmail))
			}
			break
		}
		pageToken = resp.NextPageToken
	}

	return nil
}

// DeltaSync checks for updates since startHistoryID in sub-50ms
func (s *SyncEngine) DeltaSync(
	ctx context.Context,
	accountEmail string,
	startHistoryID string,
	logger func(level, msg string),
) (int, error) {
	if s.srv == nil {
		return 0, fmt.Errorf("gmail service is not initialized")
	}

	var histID uint64
	_, err := fmt.Sscanf(startHistoryID, "%d", &histID)
	if err != nil || histID == 0 {
		return 0, fmt.Errorf("invalid history id: %s", startHistoryID)
	}

	if logger != nil {
		logger("INFO", fmt.Sprintf("[%s] Performing incremental delta sync from historyId=%d...", accountEmail, histID))
	}

	startTime := time.Now()
	call := s.srv.Users.History.List("me").
		StartHistoryId(histID).
		HistoryTypes("messageAdded", "labelAdded", "labelRemoved")

	resp, err := call.Context(ctx).Do()
	if err != nil {
		return 0, err
	}

	updatedThreadIDs := make(map[string]bool)
	for _, h := range resp.History {
		for _, added := range h.MessagesAdded {
			if added.Message != nil && added.Message.ThreadId != "" {
				updatedThreadIDs[added.Message.ThreadId] = true
			}
		}
		for _, lbl := range h.LabelsAdded {
			if lbl.Message != nil && lbl.Message.ThreadId != "" {
				updatedThreadIDs[lbl.Message.ThreadId] = true
			}
		}
		for _, lbl := range h.LabelsRemoved {
			if lbl.Message != nil && lbl.Message.ThreadId != "" {
				updatedThreadIDs[lbl.Message.ThreadId] = true
			}
		}
	}

	if len(updatedThreadIDs) > 0 {
		var batchRecords []EmailThread
		for tid := range updatedThreadIDs {
			record := s.fetchThreadSummary(ctx, tid, accountEmail)
			if record != nil {
				batchRecords = append(batchRecords, *record)
			}
		}
		_ = s.store.BatchUpsertThreads(batchRecords)
	}

	// Update local sync state with the newest historyId
	if resp.HistoryId > 0 {
		_ = s.store.SetLastHistoryID(accountEmail, fmt.Sprintf("%d", resp.HistoryId))
	}

	if logger != nil {
		logger("INFO", fmt.Sprintf("[%s] Delta sync completed in %v. %d thread changes synced.", accountEmail, time.Since(startTime).Round(time.Millisecond), len(updatedThreadIDs)))
	}

	return len(updatedThreadIDs), nil
}

func (s *SyncEngine) fetchThreadSummary(ctx context.Context, threadID, accountEmail string) *EmailThread {
	req := s.srv.Users.Threads.Get("me", threadID).
		Format("metadata").
		MetadataHeaders("Subject", "From", "Date")

	thread, err := req.Context(ctx).Do()
	if err != nil || len(thread.Messages) == 0 {
		return nil
	}

	firstMsg := thread.Messages[0]
	var subject, sender string

	if firstMsg.Payload != nil {
		for _, header := range firstMsg.Payload.Headers {
			switch header.Name {
			case "Subject":
				subject = header.Value
			case "From":
				sender = header.Value
			}
		}
	}

	if subject == "" {
		subject = "(No Subject)"
	}
	if sender == "" {
		sender = "Unknown Sender"
	}

	cat := ClassifyThread(firstMsg.LabelIds, sender, subject, thread.Snippet)

	return &EmailThread{
		ID:            thread.Id,
		AccountEmail:  accountEmail,
		HistoryID:     fmt.Sprintf("%d", thread.HistoryId),
		Snippet:       thread.Snippet,
		Subject:       subject,
		From:          sender,
		InternalDate:  firstMsg.InternalDate,
		LabelIDs:      strings.Join(firstMsg.LabelIds, ","),
		SplitCategory: cat,
	}
}

func (s *SyncEngine) FetchFullThread(ctx context.Context, threadID, accountEmail string) ([]EmailMessage, error) {
	if s.srv == nil {
		return nil, fmt.Errorf("gmail service is not initialized")
	}

	cached, err := s.store.GetMessagesForThread(threadID)
	if err == nil && len(cached) > 0 {
		for i := range cached {
			if cached[i].BodyHTML != "" {
				res := SanitizeEmailHTML(cached[i].BodyHTML)
				cached[i].BodyHTML = res.CleanHTML
				cached[i].TrackersBlocked = res.TrackersBlocked
			}
		}
		return cached, nil
	}

	fullThread, err := s.srv.Users.Threads.Get("me", threadID).Format("full").Context(ctx).Do()
	if err != nil {
		return nil, fmt.Errorf("failed to fetch thread details: %w", err)
	}

	var messages []EmailMessage

	for _, msg := range fullThread.Messages {
		var subject, sender, recipient string
		if msg.Payload != nil {
			for _, h := range msg.Payload.Headers {
				switch h.Name {
				case "Subject":
					subject = h.Value
				case "From":
					sender = h.Value
				case "To":
					recipient = h.Value
				}
			}
		}

		rawHTML, plainText, attachments := extractMessageContent(msg.Id, msg.Payload)
		sanitized := SanitizeEmailHTML(rawHTML)

		emailMsg := EmailMessage{
			ID:              msg.Id,
			AccountEmail:    accountEmail,
			ThreadID:        threadID,
			From:            sender,
			To:              recipient,
			Date:            msg.InternalDate,
			Subject:         subject,
			Snippet:         msg.Snippet,
			BodyHTML:        sanitized.CleanHTML,
			BodyText:        plainText,
			TrackersBlocked: sanitized.TrackersBlocked,
			Attachments:     attachments,
		}

		_ = s.store.UpsertMessage(emailMsg)
		for _, att := range attachments {
			_ = s.store.UpsertAttachment(att)
		}

		messages = append(messages, emailMsg)
	}

	return messages, nil
}

func (s *SyncEngine) DownloadAttachment(ctx context.Context, msgID, attachmentID, filename, threadID string) (string, error) {
	if s.srv == nil {
		return "", fmt.Errorf("gmail service is not initialized")
	}

	home, _ := os.UserHomeDir()
	targetDir := filepath.Join(home, ".fastmail", "attachments", threadID)
	_ = os.MkdirAll(targetDir, 0755)
	targetPath := filepath.Join(targetDir, filename)

	if _, err := os.Stat(targetPath); err == nil {
		return targetPath, nil
	}

	att, err := s.srv.Users.Messages.Attachments.Get("me", msgID, attachmentID).Context(ctx).Do()
	if err != nil {
		return "", fmt.Errorf("failed to download attachment: %w", err)
	}

	data, err := base64.URLEncoding.DecodeString(att.Data)
	if err != nil {
		data, err = base64.StdEncoding.DecodeString(att.Data)
		if err != nil {
			return "", fmt.Errorf("failed to decode attachment data: %w", err)
		}
	}

	if err := os.WriteFile(targetPath, data, 0644); err != nil {
		return "", fmt.Errorf("failed to write attachment to disk: %w", err)
	}

	return targetPath, nil
}

func extractMessageContent(msgID string, part *gmail.MessagePart) (htmlBody, textBody string, attachments []EmailAttachment) {
	if part == nil {
		return "", "", nil
	}

	if part.Filename != "" && part.Body != nil && part.Body.AttachmentId != "" {
		var contentID string
		for _, h := range part.Headers {
			if h.Name == "Content-ID" {
				contentID = strings.Trim(h.Value, "<>")
			}
		}

		att := EmailAttachment{
			ID:           fmt.Sprintf("%s_%s", msgID, part.Body.AttachmentId),
			MessageID:    msgID,
			Filename:     part.Filename,
			MimeType:     part.MimeType,
			Size:         part.Body.Size,
			AttachmentID: part.Body.AttachmentId,
			ContentID:    contentID,
		}
		attachments = append(attachments, att)
	}

	if part.Body != nil && part.Body.Data != "" {
		decoded, err := base64.URLEncoding.DecodeString(part.Body.Data)
		if err == nil {
			if part.MimeType == "text/html" {
				htmlBody = string(decoded)
			} else if part.MimeType == "text/plain" {
				textBody = string(decoded)
			}
		}
	}

	for _, child := range part.Parts {
		childHTML, childText, childAtts := extractMessageContent(msgID, child)
		if childHTML != "" && htmlBody == "" {
			htmlBody = childHTML
		}
		if childText != "" && textBody == "" {
			textBody = childText
		}
		attachments = append(attachments, childAtts...)
	}

	return htmlBody, textBody, attachments
}
